/// <summary>Parses a customer code from its string form.</summary>
/// <param name="code">The raw code text.</param>
/// <returns>The parsed customer code.</returns>
/// <exception cref="FormatException">Thrown when <paramref name="code"/> is not a valid customer code.</exception>
public CustomerCode Parse(string code)
{
    if (!CustomerCode.TryParse(code, out var result))
    {
        throw new FormatException("Invalid customer code.");
    }
    return result;
}

